def f(x, y):
    return 3*x**2 + 3*y**2 - (x**2 * y**2) - 8*x*y - 1

def check_condition(a):
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            if f(a[i], a[j]) < -1e-9:
                return False
    return True

