import numpy as np
from itertools import combinations
import random

def f(x, y):
    return 3*x**2 + 3*y**2 - (x**2 * y**2) - 8*x*y - 1

def check_condition(a):
    for i, j in combinations(range(len(a)), 2):
        if f(a[i], a[j]) < 0:
            return False
    return True

def search_n(n, iterations=2000000):
    for _ in range(iterations):
        a = [random.uniform(0.01, 10.0) for _ in range(n)]
        if check_condition(a):
            return a
    return None

print(f"n=3: {search_n(3)}")
print(f"n=4: {search_n(4)}")
